"""ODMM V205.1: offline capability observation panel. No NAS access. Auteur: Abdelhalim Talbi."""
import base64,hashlib,re
from odmm_unified_cockpit_v2050 import PAGE as PREVIOUS

PANEL='''<section id="capability-v2051"><h2>Capacités NFS / SMB · observations hors ligne</h2><p class="muted">Importer deux exports JSON normalisés V204.7. Déclarations utilisateur uniquement, sans certification constructeur.</p><div class="cards"><div class="card">Source · capacités<strong id="cap-src">UNVERIFIED</strong></div><div class="card">Cible · capacités<strong id="cap-dst">UNVERIFIED</strong></div><div class="card">Comparaison<strong id="cap-pair">NO_EVIDENCE</strong></div></div><label>Export source JSON <input id="cap-source-file" type="file" accept=".json,application/json"></label><label>Export cible JSON <input id="cap-target-file" type="file" accept=".json,application/json"></label><p id="cap-result" role="status" aria-live="polite">Aucune observation · Cutover interdit</p><table><thead><tr><th>Champ</th><th>Source</th><th>Cible</th><th>Évaluation</th></tr></thead><tbody id="cap-rows"></tbody></table></section>'''
SCRIPT='''<script>
'use strict';(()=>{const fields=['software_version','protocol','security_style','identity_domain','acl_model','case_sensitivity','nfs_version','smb_version'];const state={source:null,target:null};const el=id=>document.getElementById(id);function reset(){el('cap-rows').replaceChildren();el('cap-pair').textContent='UNVERIFIED';el('cap-result').textContent='Déclarations uniquement · Cutover interdit';}function render(){reset();for(const side of ['source','target'])el(side==='source'?'cap-src':'cap-dst').textContent=state[side]?.endpoint?.vendor||'UNVERIFIED';if(!state.source||!state.target)return;for(const field of fields){const a=state.source.endpoint[field]||'NON RENSEIGNÉ',b=state.target.endpoint[field]||'NON RENSEIGNÉ';const tr=document.createElement('tr');for(const value of [field,a,b,a===b&&a!=='NON RENSEIGNÉ'?'DÉCLARÉ IDENTIQUE':'À VÉRIFIER']){const td=document.createElement('td');td.textContent=value;tr.appendChild(td)}el('cap-rows').appendChild(tr)}el('cap-result').textContent='Comparaison déclarative uniquement · ACL / identités NON CERTIFIÉES · Cutover interdit';}async function load(side,file){state[side]=null;render();if(!file)return;if(file.size>1048576)throw Error('Fichier supérieur à 1 Mio');const data=JSON.parse(await file.text());if(!data||data.schema!=='odmm.offline_capabilities.v2047'||data.status!=='UNVERIFIED'||data.cutover_authorized!==false||data.evidence_type!=='USER_SUPPLIED_OFFLINE_EXPORT'||!data.endpoint||typeof data.endpoint!=='object'||!['netapp_ontap','dell_powerscale','truenas_scale'].includes(data.endpoint.vendor)||data.endpoint.capabilities_observed!==false||data.endpoint.datasheet_version_verified!==false)throw Error('Export non conforme');for(const field of fields){if(data.endpoint[field]!==undefined&&(typeof data.endpoint[field]!=='string'||data.endpoint[field].length>256))throw Error('Champ non conforme')}state[side]=data;render()}for(const [side,id] of [['source','cap-source-file'],['target','cap-target-file']])el(id).addEventListener('change',async function(){try{await load(side,this.files[0])}catch(e){el('cap-result').textContent='Import refusé : '+e.message+' · Cutover interdit'}})})();
</script>'''
PAGE=PREVIOUS.replace('</main>',PANEL+'</main>').replace('</body>',SCRIPT+'</body>').replace('V205.0','V205.1').replace('V5.6.0','V5.6.1')
def cockpit_csp():
    tags=[(tag,body) for tag in ('script','style') for body in re.findall(r'<'+tag+r'>(.*?)</'+tag+r'>',PAGE,re.S)]
    def hashes(tag):return ' '.join("'sha256-"+base64.b64encode(hashlib.sha256(body.encode()).digest()).decode()+"'" for t,body in tags if t==tag)
    return "default-src 'none'; script-src "+hashes('script')+'; style-src '+hashes('style')+"; base-uri 'none'; form-action 'none'; frame-ancestors 'none'"
def attach_capability_cockpit(app,*,authorize):
    if not callable(authorize):raise ValueError('AUTHORIZATION_PROVIDER_REQUIRED')
    from fastapi import Request,HTTPException
    from fastapi.responses import HTMLResponse
    async def page(request:Request):
        if authorize(request) is not True:raise HTTPException(403,'FORBIDDEN')
        return HTMLResponse(PAGE,headers={'Content-Security-Policy':cockpit_csp(),'Cache-Control':'no-store','X-Content-Type-Options':'nosniff'})
    app.add_api_route('/qualification/cockpit',page,methods=['GET'],include_in_schema=False)
